const caption = $('Code in JavaScript').first().json.caption;

// Je node ta run hoyeche, oitar binary nibe
let binary;

try {
  const b1 = $('Resize Image').first().binary;
  if (b1 && Object.keys(b1).length) binary = b1;
} catch (e) {}

if (!binary) {
  try {
    const b2 = $('Resize Image1').first().binary;
    if (b2 && Object.keys(b2).length) binary = b2;
  } catch (e) {}
}

if (!binary) {
  throw new Error('Resize Image ba Resize Image1 kono node theke binary pawa jayni');
}

return [{
  json: {
    caption,
    row_number: $('Upload image in sheet').first().json.row_number
  },
  binary
}];

const text = $input.first().json.output[0].content[0].text.trim();
const lang = String($('Limit').first().json.Language || '').toLowerCase().trim();
const isEnglish = ['english', 'en', 'eng'].includes(lang);

const footer = isEnglish
  ? `Call / WhatsApp to order: 01613-679668, 01841-976624
Or contact us via inbox
Visit: www.kasrioil.com`
  : `অর্ডার করতে কল / হোয়াটসঅ্যাপ করুন: 01613-679668, 01841-976624
অথবা ইনবক্সে যোগাযোগ করুন
ভিজিট করুন: www.kasrioil.com`;

return [{ json: { caption: text + '\n\n' + footer } }];
